reference_solution:
def minimum_processing_resource_cost(nums,k):
    current=k;operations=0
    for need in nums:
        if current<need:
            added=(need-current+k-1)//k;current+=added*k;operations+=added
        current-=need
    return operations*(operations+1)//2%(10**9+7)

